            'Wheat' => 'گندم پاکستان اور بہت سے دوسرے ممالک کی اہم ترین بنیادی غذائی فصلوں میں سے ایک ہے۔ یہ لاکھوں لوگوں کے لیے خوراک کا بڑا ذریعہ ہے اور آٹا بنانے کے لیے بڑے پیمانے پر استعمال ہوتی ہے، جس سے روٹی، چپاتی، بسکٹ اور دیگر بیکری مصنوعات تیار کی جاتی ہیں۔ گندم کی کاشت پاکستان کی زرعی معیشت میں اہم کردار ادا کرتی ہے کیونکہ یہ غذائی تحفظ یقینی بنانے کے ساتھ کسانوں کو آمدنی بھی فراہم کرتی ہے۔ یہ بنیادی طور پر موسم سرما میں ٹھنڈی اور خشک آب و ہوا میں اگائی جاتی ہے۔',
            'Mustard' => 'سرسوں پاکستان اور بہت سے دوسرے ممالک میں بڑے پیمانے پر اگائی جانے والی ایک اہم تیل دار فصل ہے۔ اسے بنیادی طور پر اس کے بیجوں کے لیے کاشت کیا جاتا ہے جن سے خوردنی تیل حاصل کیا جاتا ہے۔ سرسوں کی کاشت زرعی معیشت میں اہم کردار ادا کرتی ہے کیونکہ اس سے کسانوں کو آمدنی ملتی ہے اور ملک میں خوردنی تیل کی پیداوار میں اضافہ ہوتا ہے۔ یہ ٹھنڈی آب و ہوا میں اچھی نشوونما پاتی ہے اور ربیع کے موسم کی اہم فصل ہے۔',
            'Barley' => 'جو پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم اناج کی فصل ہے۔ اسے بنیادی طور پر انسانی خوراک، جانوروں کی خوراک اور مشروبات کی صنعت میں استعمال کیا جاتا ہے۔ جو دنیا کی قدیم ترین کاشت کی جانے والی فصلوں میں سے ایک ہے اور خشک اور کم زرخیز زمین میں بھی نشوونما پانے کی صلاحیت رکھتی ہے۔ یہ خاص طور پر خشک اور نیم خشک علاقوں میں مویشیوں کی خوراک اور غذائی تحفظ کے لیے اہم ہے۔',
            'Rapeseed' => 'رائی پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم تیل دار فصل ہے۔ اسے بنیادی طور پر اس کے بیجوں کے لیے کاشت کیا جاتا ہے جن سے خوردنی تیل اور جانوروں کی خوراک تیار کی جاتی ہے۔ رائی کی کاشت ملکی زرعی معیشت کے لیے اہم ہے کیونکہ اس سے درآمدی خوردنی تیل پر انحصار کم کرنے میں مدد ملتی ہے اور کسانوں کو آمدنی حاصل ہوتی ہے۔ یہ عموماً ٹھنڈی آب و ہوا میں ربیع کی فصل کے طور پر اگائی جاتی ہے۔',
            'Canola' => 'کینولا پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم تیل دار فصل ہے۔ اسے بنیادی طور پر ایسے بیجوں کے لیے کاشت کیا جاتا ہے جن سے کھانا پکانے کا خوردنی تیل تیار کیا جاتا ہے۔ کینولا کی کاشت درآمدی خوردنی تیل پر انحصار کم کرنے اور زرعی معیشت کو مضبوط بنانے میں مدد دیتی ہے۔ یہ سرد موسم کی فصل ہے اور موسم سرما کے حالات میں بہترین نشوونما پاتی ہے۔',
            'Tobacco' => 'تمباکو پاکستان سمیت بہت سے ممالک میں اگائی جانے والی ایک اہم نقد آور فصل ہے۔ اسے بنیادی طور پر اس کے پتوں کے لیے کاشت کیا جاتا ہے جنہیں سگریٹ، سگار اور تمباکو سے بنی دیگر مصنوعات میں استعمال کیا جاتا ہے۔ تمباکو کی کاشت کسانوں کو آمدنی فراہم کرنے اور صنعتی پیداوار کو سہارا دینے میں اہم کردار ادا کرتی ہے۔ تاہم یہ زیادہ قدر والی فصل ہونے کے ساتھ صحت سے متعلق حساس فصل بھی ہے، اس لیے اس کی کاشت اور انتظام میں احتیاط ضروری ہے۔',
            'Lucerne' => 'لوسرن، جسے الفالفا بھی کہا جاتا ہے، مویشیوں خصوصاً گائے، بھینس، بھیڑ اور بکریوں کے لیے سبز چارہ فراہم کرنے والی ایک اہم فصل ہے۔ یہ انتہائی غذائیت بخش اور پروٹین سے بھرپور ہوتی ہے، اسی لیے اسے دودھ دینے والے مویشیوں کے لیے بہترین سبز چاروں میں شمار کیا جاتا ہے۔ پاکستان میں لوسرن کی کاشت اس لیے اہم ہے کہ یہ دودھ کی پیداوار بہتر بنانے میں مدد دیتی ہے اور سال میں کئی بار کٹائی دی جا سکتی ہے۔ یہ طویل مدت تک قائم رہنے والی بارہماسی فصل ہے جو مناسب آبپاشی کے ساتھ مختلف آب و ہوا میں اچھی نشوونما پاتی ہے۔',
            'Fenugreek(Methi)' => 'میتھی ایک اہم پتوں والی سبزی اور مصالحے کی فصل ہے جو پاکستان سمیت بہت سے ممالک میں بڑے پیمانے پر اگائی جاتی ہے۔ اس کے تازہ پتے سبزی اور مصالحے کے طور پر جبکہ خشک بیج کھانا پکانے اور مختلف روایتی استعمالات میں کام آتے ہیں۔ میتھی اپنی خوشبو، ذائقے اور غذائی خصوصیات کی وجہ سے اہم سمجھی جاتی ہے۔ اس کی کاشت کسانوں کو مقامی منڈی میں اچھی آمدنی فراہم کر سکتی ہے اور یہ نسبتاً ٹھنڈے موسم میں اچھی نشوونما پاتی ہے۔',
            'Potato' => 'آلو پاکستان اور دنیا کے بہت سے ممالک میں اگائی جانے والی ایک اہم غذائی اور سبزی کی فصل ہے۔ اسے روزمرہ کھانوں، فرنچ فرائز، چپس اور مختلف تیار شدہ غذائی مصنوعات میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ آلو کی کاشت کسانوں کے لیے اہم آمدنی کا ذریعہ ہے کیونکہ اس کی منڈی میں مسلسل طلب رہتی ہے۔ یہ نسبتاً ٹھنڈے موسم میں اچھی نشوونما پاتا ہے اور زرخیز، اچھی نکاسی والی مٹی کو پسند کرتا ہے۔',
            'Spinach' => 'پالک ایک اہم پتوں والی سبزی ہے جو پاکستان اور بہت سے دوسرے ممالک میں بڑے پیمانے پر کاشت کی جاتی ہے۔ یہ آئرن، وٹامنز اور معدنیات سے بھرپور ہونے کی وجہ سے صحت بخش غذا کا اہم حصہ ہے۔ پالک کو تازہ سبزی، سلاد اور مختلف پکوانوں میں استعمال کیا جاتا ہے۔ یہ تیزی سے بڑھتی ہے، اس لیے کسان نسبتاً کم مدت میں اس کی کٹائی کرکے آمدنی حاصل کر سکتے ہیں۔',
            'Pea' => 'مٹر پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم دال دار اور سبزی کی فصل ہے۔ اسے تازہ سبزی کے طور پر استعمال کیا جاتا ہے اور یہ پروٹین، وٹامنز اور معدنیات کا اچھا ذریعہ ہے۔ مٹر کی کاشت کسانوں کو اچھی آمدنی فراہم کرتی ہے اور دال دار فصل ہونے کی وجہ سے مٹی میں نائٹروجن شامل کرکے اس کی زرخیزی بہتر بنانے میں بھی مدد دیتی ہے۔ یہ ٹھنڈے موسم میں بہترین نشوونما پاتا ہے۔',
            'Carrot' => 'گاجر پاکستان اور دنیا کے بہت سے حصوں میں اگائی جانے والی ایک اہم جڑ والی سبزی ہے۔ یہ بیٹا کیروٹین، وٹامنز اور غذائی ریشے سے بھرپور ہونے کی وجہ سے غذائیت کے لحاظ سے اہم ہے۔ گاجر کو سلاد، جوس، پکا ہوا کھانا اور مختلف غذائی مصنوعات میں استعمال کیا جاتا ہے۔ یہ نسبتاً ٹھنڈے موسم میں اچھی نشوونما پاتی ہے اور زرخیز، نرم اور اچھی نکاسی والی مٹی کو پسند کرتی ہے۔',
            'Onion' => 'پیاز پاکستان سمیت دنیا بھر میں اگائی جانے والی اہم ترین سبزیوں کی فصلوں میں سے ایک ہے۔ اسے اپنے تیز ذائقے اور غذائی خصوصیات کی وجہ سے روزمرہ کھانا پکانے میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ پیاز کی کاشت کسانوں کے لیے آمدنی کا اہم ذریعہ ہے کیونکہ اس کی منڈی میں مسلسل طلب رہتی ہے۔ اسے مختلف آب و ہوا میں کاشت کیا جا سکتا ہے، بشرطیکہ مٹی اور آبپاشی کی ضروریات پوری ہوں۔',
            'CauliFlower' => 'پھول گوبھی پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم سبزی کی فصل ہے۔ اسے روزمرہ کھانوں میں بڑے پیمانے پر استعمال کیا جاتا ہے اور اس کی غذائی خصوصیات اور مختلف طریقوں سے پکانے کی صلاحیت کی وجہ سے پسند کیا جاتا ہے۔ پھول گوبھی کی کاشت سبزیوں کی منڈی میں کسانوں کو آمدنی فراہم کرتی ہے اور اس کی طلب عام طور پر اچھی رہتی ہے۔ یہ نسبتاً ٹھنڈے موسم اور زرخیز، مناسب نمی والی مٹی میں بہتر نشوونما پاتی ہے۔',
            'Cabbage' => 'بند گوبھی پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم پتوں والی سبزی کی فصل ہے۔ اسے سلاد، سبزی، اچار اور مختلف پکے ہوئے کھانوں میں استعمال کیا جاتا ہے۔ بند گوبھی وٹامنز اور غذائی ریشے سے بھرپور ہوتی ہے اور اس کی منڈی میں اچھی طلب رہتی ہے۔ یہ ٹھنڈے اور معتدل موسم میں زرخیز، مناسب نمی والی مٹی پر بہترین نشوونما پاتی ہے۔',
            'Radish' => 'مولی ایک تیزی سے بڑھنے والی جڑ والی سبزی ہے جو پاکستان اور بہت سے دوسرے ممالک میں کاشت کی جاتی ہے۔ اسے تازہ سلاد، اچار اور مختلف کھانوں میں استعمال کیا جاتا ہے اور یہ وٹامنز، معدنیات اور غذائی ریشے کا اچھا ذریعہ ہے۔ مولی کم مدت میں تیار ہو جاتی ہے، اس لیے کسان جلد پیداوار حاصل کر سکتے ہیں۔ یہ ٹھنڈے موسم میں نرم اور اچھی نکاسی والی مٹی میں بہتر نشوونما پاتی ہے۔',
            'Bean' => 'لوبیا پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم دال دار اور سبزی کی فصل ہے۔ اسے تازہ سبزی اور خشک دانے دونوں صورتوں میں استعمال کیا جاتا ہے اور یہ پروٹین، وٹامنز اور معدنیات کا اچھا ذریعہ ہے۔ لوبیا کی کاشت کسانوں کو آمدنی فراہم کرتی ہے اور دال دار فصل ہونے کی وجہ سے مٹی میں نائٹروجن شامل کرکے زرخیزی بہتر بنانے میں مدد دیتی ہے۔ یہ مناسب درجہ حرارت اور اچھی نکاسی والی مٹی میں اچھی نشوونما پاتی ہے۔',
            'Lettuce' => 'سلاد پتہ ایک اہم پتوں والی سبزی ہے جو پاکستان اور دنیا کے بہت سے حصوں میں کاشت کی جاتی ہے۔ اسے بنیادی طور پر سلاد، سینڈوچ اور مختلف تازہ کھانوں میں استعمال کیا جاتا ہے۔ اس میں پانی کی مقدار زیادہ اور کیلوریز کم ہوتی ہیں، جبکہ مختلف وٹامنز اور معدنیات بھی پائے جاتے ہیں۔ سلاد پتے کی فصل نسبتاً ٹھنڈے موسم میں اچھی نشوونما پاتی ہے اور مناسب آبپاشی کے ساتھ جلد تیار ہو جاتی ہے۔',
            'Garlic' => 'لہسن پاکستان اور دنیا کے بہت سے ممالک میں اگائی جانے والی ایک اہم مصالحے اور غذائی فصل ہے۔ اسے روزمرہ کھانا پکانے، اچار اور مختلف غذائی مصنوعات میں ذائقہ اور خوشبو پیدا کرنے کے لیے استعمال کیا جاتا ہے۔ لہسن اپنی غذائی اور روایتی ادویاتی خصوصیات کی وجہ سے بھی اہم سمجھا جاتا ہے۔ یہ ٹھنڈے اور خشک موسم میں اچھی نشوونما پاتا ہے اور زرخیز، اچھی نکاسی والی مٹی کو پسند کرتا ہے۔',
            'Beetroot' => 'چقندر ایک اہم جڑ والی سبزی ہے جو پاکستان اور بہت سے دوسرے ممالک میں کاشت کی جاتی ہے۔ اس کی جڑ کو تازہ، سلاد، جوس اور مختلف غذائی مصنوعات میں استعمال کیا جاتا ہے۔ چقندر قدرتی رنگ، غذائی ریشے اور مختلف وٹامنز اور معدنیات کا ذریعہ ہے۔ یہ ٹھنڈے اور معتدل موسم میں نرم، زرخیز اور اچھی نکاسی والی مٹی میں بہتر نشوونما پاتا ہے۔',
            'Turnip' => 'شلجم پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم جڑ والی سبزی ہے۔ اسے پکا کر، اچار اور مختلف روایتی کھانوں میں استعمال کیا جاتا ہے اور اس کے پتے بھی بطور سبزی کھائے جاتے ہیں۔ شلجم وٹامنز، معدنیات اور غذائی ریشے کا اچھا ذریعہ ہے۔ یہ ٹھنڈے موسم میں تیزی سے نشوونما پاتا ہے اور مناسب نمی والی زرخیز مٹی میں اچھی پیداوار دیتا ہے۔',
            'Linseed' => 'السی ایک اہم تیل دار اور صنعتی فصل ہے جو پاکستان اور بہت سے دوسرے ممالک میں کاشت کی جاتی ہے۔ اس کے بیجوں سے خوردنی اور صنعتی تیل حاصل کیا جاتا ہے اور ان میں اومیگا-3 سمیت مفید چکنائیاں پائی جاتی ہیں۔ السی کی کاشت کسانوں کو آمدنی فراہم کرتی ہے اور تیل کی صنعت کے لیے خام مال مہیا کرتی ہے۔ یہ ٹھنڈی اور خشک آب و ہوا میں زرخیز اور اچھی نکاسی والی مٹی پر بہتر نشوونما پاتی ہے۔',
            'Coriander' => 'دھنیا پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم مصالحے اور جڑی بوٹی کی فصل ہے۔ اسے کھانا پکانے، سلاد، اچار اور روایتی ادویات میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ اس کے تازہ سبز پتے اور خشک بیج دونوں غذائی استعمال کے لحاظ سے اہم ہیں۔ دھنیا اپنی مقامی اور برآمدی منڈیوں میں اچھی طلب کی وجہ سے کسانوں کو اچھی آمدنی فراہم کرتا ہے اور ٹھنڈی، خشک آب و ہوا میں معتدل آبپاشی کے ساتھ بہتر نشوونما پاتا ہے۔',
            'SunFlower' => 'سورج مکھی پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم تیل دار فصل ہے۔ اسے بنیادی طور پر خوردنی تیل اور جانوروں کی خوراک کے لیے کاشت کیا جاتا ہے۔ سورج مکھی کا تیل کھانا پکانے میں بڑے پیمانے پر استعمال ہوتا ہے اور اسے غذائی خصوصیات کی وجہ سے اہم سمجھا جاتا ہے۔ یہ فصل کم مدت میں تیار ہو جاتی ہے، اس لیے کسانوں کے لیے اچھی آمدنی کا ذریعہ بن سکتی ہے، اور گرم آب و ہوا، مناسب دھوپ اور معتدل آبپاشی میں بہترین نشوونما پاتی ہے۔',
            'Isabgol' => 'اسپغول پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم ادویاتی فصل ہے۔ اسے بنیادی طور پر بیج اور چھلکے کے لیے کاشت کیا جاتا ہے، جنہیں جڑی بوٹیوں سے تیار ادویات اور نظامِ ہاضمہ سے متعلق مصنوعات میں استعمال کیا جاتا ہے۔ اسپغول ہاضمہ بہتر بنانے اور قبض سے نجات میں مدد کے لیے مشہور ہے۔ دواسازی اور برآمدی منڈیوں میں اس کی زیادہ طلب کسانوں کے لیے اچھی آمدنی کا ذریعہ بنتی ہے، جبکہ یہ ٹھنڈی اور خشک آب و ہوا میں کم نمی کے ساتھ بہتر نشوونما پاتا ہے۔',
            'Broccoli' => 'بروکلی پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی غذائیت سے بھرپور سبزی کی فصل ہے۔ یہ بند گوبھی کے خاندان سے تعلق رکھتی ہے اور اسے سلاد، سوپ اور مختلف پکے ہوئے کھانوں میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ اس کی زیادہ غذائی قدر اور منڈی میں بڑھتی ہوئی طلب کی وجہ سے بروکلی کی کاشت مقبول ہو رہی ہے۔ یہ ٹھنڈے موسم اور مناسب نمی والی زرخیز مٹی میں بہترین نشوونما پاتی ہے۔',
            'Orange' => 'مالٹا پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی اہم پھلوں کی فصلوں میں سے ایک ہے۔ اسے اس کے میٹھے ذائقے، تازگی بخش رس اور وٹامنز کی زیادہ مقدار کی وجہ سے بڑے پیمانے پر استعمال کیا جاتا ہے۔ مالٹے کی کاشت زرعی معیشت میں اہم کردار ادا کرتی ہے کیونکہ اس سے کسانوں کو آمدنی ملتی ہے اور پھلوں کی برآمدی صنعت کو سہارا ملتا ہے۔ پاکستان اعلیٰ معیار کے کینو کی پیداوار کے لیے بھی مشہور ہے۔ مالٹا معتدل پانی کی فراہمی کے ساتھ گرم آب و ہوا میں بہتر نشوونما پاتا ہے۔',
            'Kinnow' => 'کینو پاکستان میں اگائی جانے والی اہم ترین ترشاوہ پھلوں کی فصلوں میں سے ایک ہے۔ یہ اپنے میٹھے ذائقے، رس بھرے گودے اور وٹامنز کی زیادہ مقدار کی وجہ سے مشہور ہے۔ پاکستان دنیا میں کینو پیدا کرنے اور برآمد کرنے والے بڑے ممالک میں شامل ہے۔ کینو کی کاشت زرعی معیشت میں اہم کردار ادا کرتی ہے کیونکہ اس سے کسانوں کو آمدنی ملتی ہے اور برآمدی صنعت کو سہارا ملتا ہے۔ یہ گرم آب و ہوا، معتدل آبپاشی اور زرخیز مٹی میں بہترین نشوونما پاتا ہے۔',
            'Lemon' => 'لیموں پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم ترشاوہ پھلوں کی فصل ہے۔ اسے جوس، کھانا پکانے، ادویات اور غذائی صنعت میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ لیموں وٹامن سی سے بھرپور ہوتا ہے اور اپنے تازگی بخش ذائقے اور صحت سے متعلق فوائد کی وجہ سے مقبول ہے۔ لیموں کی کاشت کسانوں کو اچھی آمدنی فراہم کرتی ہے اور مقامی منڈیوں اور برآمدی صنعت کو سہارا دیتی ہے۔ یہ مناسب دھوپ اور آبپاشی کے ساتھ گرم آب و ہوا میں بہترین نشوونما پاتا ہے۔',
            'GrapeFruit' => 'چکوترا ایک اہم ترشاوہ پھلوں کی فصل ہے جو پاکستان سمیت دنیا کے بہت سے گرم علاقوں میں اگائی جاتی ہے۔ یہ اپنے قدرے کھٹے اور میٹھے ذائقے کے لیے مشہور ہے اور اسے جوس، سلاد، ادویات اور مختلف غذائی مصنوعات میں استعمال کیا جاتا ہے۔ چکوترے کی کاشت کسانوں کو آمدنی فراہم کرتی ہے اور پھلوں کی برآمدی صنعت کو سہارا دیتی ہے۔ یہ وٹامنز، معدنیات اور اینٹی آکسیڈنٹس سے بھرپور ہوتا ہے اور مناسب دھوپ اور آبپاشی کے ساتھ گرم آب و ہوا میں بہتر نشوونما پاتا ہے۔',
            'Sweet Lime' => 'موسمی ایک اہم ترشاوہ پھلوں کی فصل ہے جو پاکستان اور بہت سے دوسرے ممالک میں اگائی جاتی ہے۔ یہ اپنے میٹھے ذائقے، تازگی بخش رس اور صحت سے متعلق فوائد کی وجہ سے مشہور ہے۔ موسمی کو تازہ پھل کے طور پر اور جوس اور بعض روایتی مصنوعات میں استعمال کیا جاتا ہے۔ یہ فصل کسانوں کو اچھی آمدنی فراہم کرتی ہے اور مقامی پھلوں کی منڈیوں کو سہارا دیتی ہے۔ موسمی مناسب دھوپ اور آبپاشی کے ساتھ گرم آب و ہوا میں بہترین نشوونما پاتی ہے۔',
            'Pomegranate' => 'انار پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم پھلوں کی فصل ہے۔ یہ اپنے میٹھے اور رسیلے دانوں اور زیادہ غذائی قدر کے لیے مشہور ہے۔ انار کی کاشت کسانوں کے لیے اچھی آمدنی کا ذریعہ ہے کیونکہ مقامی اور برآمدی منڈیوں میں اس کی طلب زیادہ ہے۔ اسے تازہ استعمال کے علاوہ جوس، مٹھائیوں، ادویات اور مختلف غذائی مصنوعات میں بھی استعمال کیا جاتا ہے۔ انار گرم اور خشک آب و ہوا میں بہترین نشوونما پاتا ہے۔',
            'Apple' => 'سیب پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی اہم ترین پھلوں کی فصلوں میں سے ایک ہے۔ اسے اس کے لذیذ ذائقے، غذائی فوائد اور معاشی اہمیت کی وجہ سے خاص قدر حاصل ہے۔ سیب کی کاشت کسانوں کو آمدنی فراہم کرتی ہے اور پھلوں کی برآمدی صنعت کو سہارا دیتی ہے۔ سیب تازہ کھانے کے علاوہ جوس، جام، مٹھائیوں اور بیکری مصنوعات میں بھی استعمال ہوتا ہے۔ سیب کے درخت ٹھنڈی آب و ہوا اور موسم سرما میں مناسب سردی والے علاقوں میں بہترین نشوونما پاتے ہیں۔',
            'Date' => 'کھجور خشک اور نیم خشک علاقوں، خصوصاً پاکستان میں، اگائی جانے والی اہم ترین پھلوں کی فصلوں میں سے ایک ہے۔ اسے قدرتی مٹھاس کے طور پر بڑے پیمانے پر استعمال کیا جاتا ہے اور یہ توانائی اور غذائی اجزا سے بھرپور ہوتی ہے۔ کھجور کی کاشت جنوبی پاکستان کی معیشت میں اہم کردار ادا کرتی ہے، خصوصاً سندھ اور بلوچستان میں۔ اسے غذائی مصنوعات، مٹھائیوں اور روایتی ادویات میں بھی استعمال کیا جاتا ہے۔ پاکستان دنیا میں اعلیٰ معیار کی کھجور پیدا کرنے والے اہم ممالک میں شامل ہے۔',
            'Mint' => 'پودینہ ایک اہم خوشبودار جڑی بوٹی ہے جسے خوراک، ادویات اور کاسمیٹکس میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ یہ اپنی تازگی بخش خوشبو اور ٹھنڈک کے اثر کی وجہ سے مشہور ہے۔ پودینے کی کاشت مقبول ہے کیونکہ یہ تیزی سے بڑھتا ہے اور سال میں کئی مرتبہ اس کی کٹائی کی جا سکتی ہے۔ پاکستان میں پودینہ چٹنی، سلاد، مشروبات اور جڑی بوٹیوں سے تیار روایتی مصنوعات میں عام طور پر استعمال ہوتا ہے۔ یہ ہاضمے اور سانس کی صحت سے متعلق روایتی استعمالات کے لیے بھی جانا جاتا ہے۔',
            'Fennel' => 'سونف ایک اہم مصالحے اور ادویاتی فصل ہے جو خوشبودار بیجوں کے لیے بڑے پیمانے پر اگائی جاتی ہے۔ اسے کھانا پکانے، مٹھائی سازی، جڑی بوٹیوں سے تیار ادویات اور منہ کی تازگی کے لیے استعمال کیا جاتا ہے۔ پاکستان میں سونف کی کاشت خصوصاً سندھ اور پنجاب میں اہم ہے۔ مقامی اور بین الاقوامی منڈیوں میں زیادہ طلب کی وجہ سے اس کی تجارتی قدر بھی زیادہ ہے۔ سونف اپنی میٹھی خوشبو اور ہاضمے سے متعلق فوائد کے لیے مشہور ہے۔',
            'Rice' => 'چاول پاکستان اور بہت سے دوسرے ممالک کی اہم ترین غذائی فصلوں میں سے ایک ہے۔ یہ لاکھوں لوگوں کے لیے خوراک کا بڑا ذریعہ ہے اور روزمرہ کھانوں میں بڑے پیمانے پر استعمال ہوتا ہے۔ چاول کی کاشت زرعی معیشت میں اہم کردار ادا کرتی ہے کیونکہ اس سے کسانوں کو آمدنی ملتی ہے اور برآمدی صنعت کو سہارا ملتا ہے۔ پاکستان اعلیٰ معیار کے باسمتی چاول کی پیداوار کے لیے مشہور ہے۔ چاول بنیادی طور پر گرم اور مرطوب آب و ہوا میں مناسب پانی کی دستیابی کے ساتھ اگایا جاتا ہے۔',
            'Cotton' => 'کپاس پاکستان اور دنیا کی اہم ترین نقد آور فصلوں میں سے ایک ہے۔ اسے بنیادی طور پر ریشے کے لیے کاشت کیا جاتا ہے، جس سے ٹیکسٹائل صنعت میں کپڑے، دھاگے اور دیگر مصنوعات تیار کی جاتی ہیں۔ کپاس پاکستان کی معیشت میں اہم کردار ادا کرتی ہے کیونکہ یہ کسانوں، صنعتوں اور برآمدات کو سہارا دیتی ہے۔ اس کی زیادہ معاشی قدر کی وجہ سے اسے اکثر سفید سونا بھی کہا جاتا ہے۔',
            'Sugarcane' => 'گنا پاکستان اور بہت سے گرم ممالک میں اگائی جانے والی ایک اہم نقد آور فصل ہے۔ اسے بنیادی طور پر چینی بنانے کے لیے کاشت کیا جاتا ہے، تاہم اس سے راب، ایتھنول اور گڑ بھی تیار کیا جاتا ہے۔ گنے کی کاشت زرعی معیشت میں اہم کردار ادا کرتی ہے کیونکہ یہ شوگر ملوں کو خام مال فراہم کرتی ہے اور کسانوں کے لیے آمدنی کا ذریعہ بنتی ہے۔ پاکستان دنیا میں گنا پیدا کرنے والے اہم ممالک میں شامل ہے۔',
            'Maize (Corn)' => 'مکئی پاکستان اور دنیا بھر میں اگائی جانے والی اہم ترین اناج کی فصلوں میں سے ایک ہے۔ اسے انسانی خوراک اور جانوروں کی خوراک دونوں کے طور پر استعمال کیا جاتا ہے۔ مکئی ایک اہم صنعتی فصل بھی ہے جس سے نشاستہ، مکئی کا تیل، گلوکوز اور ایتھنول تیار کیے جاتے ہیں۔ پاکستان میں غذائی تحفظ اور مویشی پالنے کے شعبے میں مکئی کا اہم کردار ہے۔',
            'Sorghum' => 'جوار پاکستان اور بہت سے دوسرے ممالک کے خشک اور نیم خشک علاقوں میں اگائی جانے والی ایک اہم اناج اور چارے کی فصل ہے۔ اسے انسانی خوراک، جانوروں کی خوراک اور چارے کے طور پر استعمال کیا جاتا ہے۔ جوار خشک سالی کو برداشت کرنے کی بھرپور صلاحیت رکھتا ہے اور خشک علاقوں میں خوراک اور چارے کے تحفظ کو یقینی بنانے میں اہم کردار ادا کرتا ہے۔ جنوبی ایشیا میں اسے عام طور پر جوار کے نام سے جانا جاتا ہے۔',
            'Pearl Millet' => 'باجرا پاکستان اور دیگر خشک ممالک کے خشک اور نیم خشک علاقوں میں اگائی جانے والی ایک اہم اناج اور چارے کی فصل ہے۔ یہ فصل خشک سالی کو برداشت کرنے کی بھرپور صلاحیت رکھتی ہے اور اسے بنیادی طور پر انسانی خوراک اور مویشیوں کے چارے کے لیے استعمال کیا جاتا ہے۔ خشک علاقوں میں کاشت کے نظام کے تحت غذائی تحفظ یقینی بنانے میں باجرے کا اہم کردار ہے۔',
            'Bottle Gourd' => 'لوکی، جسے بعض علاقوں میں گھیا بھی کہا جاتا ہے، پاکستان اور بہت سے گرم ممالک میں اگائی جانے والی ایک اہم سبزی کی فصل ہے۔ اسے زیادہ غذائی قدر اور آسان ہاضمے کی وجہ سے روزمرہ کھانوں میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ لوکی تیزی سے بڑھنے والی بیل دار فصل ہے اور سبزیوں کی کاشت اور گھریلو غذائیت میں اہم کردار ادا کرتی ہے۔',
            'Okra' => 'بھنڈی، جسے لیڈی فنگر بھی کہا جاتا ہے، پاکستان اور بہت سے گرم و نیم گرم علاقوں میں اگائی جانے والی ایک اہم سبزی کی فصل ہے۔ اسے ذائقے اور غذائی قدر کی وجہ سے روزمرہ کھانا پکانے میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ بھنڈی تیزی سے بڑھنے والی سبزی ہے جو کسانوں کو اچھی آمدنی فراہم کرتی ہے اور مقامی منڈیوں میں اس کی طلب زیادہ رہتی ہے۔',
            'Tomato' => 'ٹماٹر پاکستان اور دنیا بھر میں بڑے پیمانے پر اگائی جانے والی اہم سبزیوں کی فصلوں میں سے ایک ہے۔ یہ روزمرہ کھانا پکانے کا لازمی جزو ہے اور اسے سلاد، سالن، چٹنی، کیچپ اور مختلف تیار شدہ غذائی مصنوعات میں استعمال کیا جاتا ہے۔ مقامی اور بین الاقوامی منڈیوں میں زیادہ طلب کی وجہ سے ٹماٹر کی کاشت کسانوں کو اچھی آمدنی فراہم کرتی ہے۔',
            'Pumpkin' => 'کدو پاکستان اور بہت سے دوسرے ممالک میں اگائی جانے والی ایک اہم سبزی کی فصل ہے۔ اسے کھانا پکانے، سوپ، مٹھائیوں اور روایتی پکوانوں میں بڑے پیمانے پر استعمال کیا جاتا ہے۔ کدو غذائیت سے بھرپور ہے اور وٹامنز، معدنیات اور غذائی ریشے فراہم کرتا ہے۔ یہ زمین پر پھیلنے والی بیل دار فصل ہے جو گرم آب و ہوا میں اچھی نشوونما پاتی ہے اور کسانوں کو اچھی آمدنی فراہم کر سکتی ہے۔',
        ];

        $prefix = preg_replace('/\(.*$/', '', $crop);
        if (isset($map[$crop]) && (stripos(ltrim($text), $crop) === 0 || ($prefix !== $crop && stripos(ltrim($text), $prefix) === 0))) {
            return $map[$crop];
        }
        return null;
    }
}
